void EXTI2_3_IRQHandler() {
    if (EXTI->RPR1 & (1 << 2)) {
        EXTI->RPR1 |= (1 << 2);
        generate_next_item();
    } 
}

void TIM3_IRQHandler() {
    // static uint16_t servo_1_pos = SERVO_MID_US;

    if (TIM3->SR & (1 << 0)) {
        TIM3->SR &= ~(1 << 0);

        if (pin_read(GPIOA, 8)) {
            TIM3->CCR2 = SERVO_MIN_US;
        } else if (pin_read(GPIOA, 11) || pin_read(GPIOA, 3)) {
            TIM3->CCR2 = SERVO_MAX_US;
        } else {
            TIM3->CCR2 = SERVO_MID_US;
        }
    }
}

